 @Test public void realTapCompassOpensAllOwnThoughtsAndClosesOcean()throws Exception{run("records.push({id:'tap-one',role:'user',text:'Первая мысль',intent:true},{id:'tap-two',role:'user',text:'Вторая мысль',intent:true});render()");String raw=js(a.shell,"JSON.stringify((()=>{let r=$('oceanToggle').getBoundingClientRect();return {x:r.x+r.width/2,y:r.y+r.height/2}})())");JSONObject point=new JSONObject((String)new JSONTokener(raw).nextValue());int[] loc=new int[2];scenario.onActivity(v->v.shell.getLocationOnScreen(loc));float d=a.getResources().getDisplayMetrics().density,x=(float)point.getDouble("x")*d+loc[0],y=(float)point.getDouble("y")*d+loc[1];for(int i=0;i<2;i++){long t=SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(t,t,MotionEvent.ACTION_DOWN,x,y,0),up=MotionEvent.obtain(t,t+80,MotionEvent.ACTION_UP,x,y,0);try{InstrumentationRegistry.getInstrumentation().sendPointerSync(down);InstrumentationRegistry.getInstrumentation().sendPointerSync(up);}finally{down.recycle();up.recycle();}if(i==0)until(()->"true".equals(js(a.shell,"OceanUI.active&&document.querySelectorAll('.thought-bubble').length===2&&$('oceanCard').hidden")));else until(()->"true".equals(js(a.shell,"!OceanUI.active")));}}

